Below is a **complete, production‑ready** example of an Express controller that

1. **Validates** the incoming payload (you can swap the `Joi` schema for any validator you prefer).  
2. **Hashes** the password with `bcrypt`.  
3. **Creates** the user document with Mongoose (or any ORM you use).  
4. **Generates** a signed JWT that you can return to the client (or set as an HttpOnly cookie).  
5. **Handles** the most common error cases (validation, duplicate e‑mail, unexpected server errors).

> **Assumptions**  
> * You are using **Node.js ≥ 14**, **Express**, **Mongoose**, **bcryptjs**, **jsonwebtoken**, and **Joi** (or any other validation lib).  
> * The `User` model has the fields `name`, `email`, `password`, `role`.  
> * A secret key for signing JWTs is stored in `process.env.JWT_SECRET`.  
> * Token expiration is configurable via `process.env.JWT_EXPIRES_IN` (e.g. `"7d"`).

---

## 1️⃣  Model (Mongoose)

```js
// models/User.js
const mongoose = require('mongoose');
const bcrypt   = require('bcryptjs');

const userSchema = new mongoose.Schema(
  {
    name: {
      type: String,
      required: [true, 'Name is required'],
      trim: true,
    },
    email: {
      type: String,
      required: [true, 'E‑mail is required'],
      unique: true,
      lowercase: true,
      trim: true,
      match: [
        /^\w+([.-]?\w+)*@\w+([.-]?\w+)*(\.\w{2,3})+$/,
        'Please provide a valid e‑mail address',
      ],
    },
    password: {
      type: String,
      required: [true, 'Password is required'],
      minlength: 6,
      select: false, // never return password in queries
    },
    role: {
      type: String,
      enum: ['user', 'admin'],
      default: 'user',
    },
  },
  { timestamps: true }
);

/* Hash password before saving */
userSchema.pre('save', async function (next) {
  // Only hash when the password field is modified (or on create)
  if (!this.isModified('password')) return next();

  const salt = await bcrypt.genSalt(12);
  this.password = await bcrypt.hash(this.password, salt);
  next();
});

/* Helper to compare passwords */
userSchema.methods.comparePassword = async function (candidatePwd) {
  return bcrypt.compare(candidatePwd, this.password);
};

module.exports = mongoose.model('User', userSchema);
```

---

## 2️⃣  Validation Schema (Joi)

```js
// validation/user.validation.js
const Joi = require('joi');

exports.createUserSchema = Joi.object({
  name: Joi.string().trim().min(2).max(100).required(),
  email: Joi.string().email({ minDomainSegments: 2 }).required(),
  password: Joi.string().min(6).max(128).required(),
  role: Joi.string().valid('user', 'admin').default('user'),
});
```

---

## 3️⃣  JWT Utility

```js
// utils/jwt.js
const jwt = require('jsonwebtoken');

exports.signJwt = (payload) => {
  const secret = process.env.JWT_SECRET;
  const expiresIn = process.env.JWT_EXPIRES_IN || '7d';

  return jwt.sign(payload, secret, { expiresIn });
};
```

---

## 4️⃣  Controller Method

```js
// controllers/auth.controller.js
const User               = require('../models/User');
const { createUserSchema } = require('../validation/user.validation');
const { signJwt }        = require('../utils/jwt');

/**
 * @desc   Register a new user and return a JWT
 * @route  POST /api/v1/auth/register
 * @access Public
 */
exports.register = async (req, res, next) => {
  try {
    /* ---------- 1️⃣  Validate request body ---------- */
    const { error, value: validatedBody } = createUserSchema.validate(req.body, {
      abortEarly: false, // return all errors
      stripUnknown: true, // remove extra fields
    });

    if (error) {
      const messages = error.details.map((d) => d.message);
      return res.status(400).json({ success: false, errors: messages });
    }

    const { name, email, password, role } = validatedBody;

    /* ---------- 2️⃣  Check for duplicate e‑mail ---------- */
    const existing = await User.findOne({ email });
    if (existing) {
      return res
        .status(409)
        .json({ success: false, message: 'E‑mail already in use' });
    }

    /* ---------- 3️⃣  Create the user (password will be hashed by pre‑save hook) ---------- */
    const newUser = await User.create({ name, email, password, role });

    /* ---------- 4️⃣  Generate JWT ---------- */
    const token = signJwt({ id: newUser._id, role: newUser.role });

    /* ---------- 5️⃣  Respond (omit password, optionally set HttpOnly cookie) ---------- */
    // Option A – return token in JSON body (most common for SPAs)
    return res.status(201).json({
      success: true,
      data: {
        user: {
          id: newUser._id,
          name: newUser.name,
          email: newUser.email,
          role: newUser.role,
          createdAt: newUser.createdAt,
        },
        token,
      },
    });

    // Option B – set token as HttpOnly cookie (safer for XSS‑prone clients)
    // res
    //   .cookie('token', token, {
    //     httpOnly: true,
    //     secure: process.env.NODE_ENV === 'production',
    //     sameSite: 'strict',
    //     maxAge: 1000 * 60 * 60 * 24 * 7, // 7 days
    //   })
    //   .status(201)
    //   .json({ success: true, data: { user: { ... } } });
  } catch (err) {
    /* ---------- 6️⃣  Unexpected errors ---------- */
    console.error('❌ Register error:', err);
    return res
      .status(500)
      .json({ success: false, message: 'Server error. Please try again later.' });
  }
};
```

---

## 5️⃣  Wire It Up (Express Router)

```js
// routes/auth.routes.js
const express = require('express');
const router  = express.Router();
const { register } = require('../controllers/auth.controller');

router.post('/register', register);

module.exports = router;
```

```js
// server.js (or app.js)
require('dotenv').config();
const express = require('express');
const mongoose = require('mongoose');
const authRoutes = require('./routes/auth.routes');

const app = express();

app.use(express.json()); // parse JSON bodies

// Connect to MongoDB
mongoose
  .connect(process.env.MONGODB_URI, {
    useNewUrlParser: true,
    useUnifiedTopology: true,
  })
  .then(() => console.log('✅ MongoDB connected'))
  .catch((e) => {
    console.error('❌ MongoDB connection error:', e);
    process.exit(1);
  });

// Register routes
app.use('/api/v1/auth', authRoutes);

// Global error handler (optional)
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);
  res
    .status(err.status || 500)
    .json({ success: false, message: err.message || 'Internal Server Error' });
});

const PORT = process.env.PORT || 5000;
app.listen(PORT, () => console.log(`🚀 Server listening on ${PORT}`));
```

---

## 📌  Quick Checklist

| ✅ | Item |
|---|------|
| **Input validation** – `Joi` schema (or any validator). |
| **Password security** – `bcrypt` with a salt factor of 12 (adjust as needed). |
| **Duplicate‑email guard** – early `findOne` check (or rely on MongoDB unique index + catch `E11000`). |
| **JWT payload** – only non‑sensitive data (`id`, `role`). |
| **Secret management** – keep `JWT_SECRET` out of source control (use `.env`). |
| **Expiration** – set via `JWT_EXPIRES_IN` (`7d`, `1h`, etc.). |
| **Response shape** – `success`, `data.user`, `token`. |
| **Error handling** – return proper HTTP status codes (`400`, `409`, `500`). |
| **Optional cookie** – `httpOnly`, `secure`, `sameSite` for extra XSS protection. |

You now have a **single, reusable controller method** that creates a user, persists it, and returns a JWT ready for authentication in subsequent requests. Feel free to adapt the validation, role handling, or token storage (e.g., refresh‑token flow) to match your specific business rules. Happy coding! 🚀

