## 3️⃣  JavaScript – `app.js`

```js
// Global map variable so other functions can use it
let map;

/**
 * Called automatically by the Maps API once it finishes loading.
 */
function initMap() {
  // Default centre (used while we wait for the user's location)
  const defaultCenter = { lat: 0, lng: 0 };

  // Create the map instance
  map = new google.maps.Map(document.getElementById('map'), {
    center: defaultCenter,
    zoom: 2,               // world view while we locate the user
    mapTypeControl: false // optional UI cleanup
  });

  // Try to get the user's current location
  if (navigator.geolocation) {
    navigator.geolocation.getCurrentPosition(
      position => {
        const userPos = {
          lat: position.coords.latitude,
          lng: position.coords.longitude
        };

        // Re‑center the map on the user and zoom in
        map.setCenter(userPos);
        map.setZoom(15);

        // Add a marker for the user
        new google.maps.Marker({
          position: userPos,
          map,
          title: 'You are here',
          // optional: a custom icon
          // icon: 'https://maps.google.com/mapfiles/ms/icons/blue-dot.png'
        });
      },
      error => {
        console.warn('Geolocation failed: ', error);
        // Keep the default centre/zoom – you could show a friendly message.
      },
      {
        enableHighAccuracy: true,
        timeout: 8000,
        maximumAge: 0
      }
    );
  } else {
    console.warn('Browser does not support Geolocation');
  }

  // -----------------------------------------------------------------
  // OPTIONAL: Click‑to‑add markers (demo purpose)
  // -----------------------------------------------------------------
  map.addListener('click', e => {
    const marker = new google.maps.Marker({
      position: e.latLng,
      map,
      title: `Marker ${Date.now()}`
    });

    // Example: open an InfoWindow when the marker is clicked
    const info = new google.maps.InfoWindow({
      content: `<p>Lat: ${e.latLng.lat().toFixed(5)}<br>Lng: ${e.latLng.lng().toFixed(5)}</p>`
    });
    marker.addListener('click', () => info.open(map, marker));
  });
}
```

### What the code does

| Step | Code snippet | Explanation |
|------|--------------|-------------|
| **Create map** | `new google.maps.Map(...)` | Instantiates the map inside the `<div id="map">`. |
| **Get user location** | `navigator.geolocation.getCurrentPosition(...)` | Uses the browser’s HTML5 Geolocation API (asks the user for permission). |
| **Center & zoom** | `map.setCenter(userPos); map.setZoom(15);` | Moves the map to the user’s coordinates and zooms to a street‑level view. |
| **Add a marker** | `new google.maps.Marker({position: userPos, map});` | Shows a pin at the user’s location. |
| **Add markers on click** | `map.addListener('click', …)` | Demonstrates how to create additional markers wherever the user taps/clicks. |

