### 4.6 Map Page – Google Maps + Markers

```jsx
// src/pages/MapPage.jsx
import { useEffect, useState, useCallback } from 'react';
import { GoogleMap, Marker, InfoWindow, useJsApiLoader } from '@react-google-maps/api';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';

const mapContainerStyle = { width: '100%', height: '80vh' };
const defaultCenter = { lat: 40.7128, lng: -74.006 }; // NYC fallback

export default function MapPage() {
  const navigate = useNavigate();
  const [locations, setLocations] = useState([]);
  const [activeMarker, setActiveMarker] = useState(null);

  // Load Google Maps script (key stored in .env)
  const { isLoaded, loadError } = useJsApiLoader({
    googleMapsApiKey: import.meta.env.VITE_GOOGLE_MAPS_KEY, // Vite syntax; adjust for CRA/Next
    libraries: ['places'],
  });

  // Fetch all locations once
  useEffect(() => {
    axios.get('/api/locations').then((res) => setLocations(res.data.locations));
  }, []);

  const handleMarkerClick = (loc) => {
    setActiveMarker(loc.id);
  };

  const handleInfoWindowClose = () => {
    setActiveMarker(null);
  };

  const handleViewDetails = (id) => {
    navigate(`/location/${id}`);
  };

  if (loadError) return <div>Failed to load Google Maps.</div>;
  if (!isLoaded) return <div>Loading map…</div>;

  return (
    <GoogleMap
      mapContainerStyle={mapContainerStyle}
      zoom={5}
      center={locations[0] ? { lat: locations[0].lat, lng: locations[0].lng } : defaultCenter}
    >
      {locations.map((loc) => (
        <Marker
          key={loc.id}
          position={{ lat: loc.lat, lng: loc.lng }}
          onClick={() => handleMarkerClick(loc)}
        >
          {activeMarker === loc.id && (
            <InfoWindow onCloseClick={handleInfoWindowClose}>
              <div className="p-2">
                <h3 className="font-semibold">{loc.name}</h3>
                <button
                  className="mt-2 bg-blue-600 text-white px-3 py-1 rounded hover:bg-blue-700"
                  onClick={() => handleViewDetails(loc.id)}
                >
                  View Details
                </button>
              </div>
            </InfoWindow>
          )}
        </Marker>
      ))}
    </GoogleMap>
  );
}
```

**Key points**

* `useJsApiLoader` lazily loads the Google Maps script **once**.  
* Markers are rendered from the **full list** you fetched from `/api/locations`.  
* Clicking a marker opens an `InfoWindow` that contains the location name **and** a button that routes to `/location/:id`.  
* The map automatically recenters on the first location (or a fallback).  

> **Performance tip** – If you have > 500 markers, wrap them in `MarkerClusterer` (provided by `@react-google-maps/api`). It reduces DOM nodes and keeps the UI snappy.

### 4.7 Location Page – Details + Full List

```jsx
// src/pages/LocationPage.jsx
import { useEffect, useState } from 'react';
import { useParams, Link } from 'react-router-dom';
import axios from 'axios';

export default function LocationPage() {
