    axios.get(`/api/locations/${id}`).then((res) => setLocation(res.data.location));
  }, [id]);

  // Load the full list (could be cached globally)
  useEffect(() => {
    axios.get('/api/locations').then((res) => setAllLocations(res.data.locations));
  }, []);

  if (!location) return <div>Loading location…</div>;

  return (
    <div className="grid md:grid-cols-3 gap-6">
      {/* Left column – selected location details */}
      <section className="md:col-span-2 p-4 border rounded bg-white">
        <h2 className="text-2xl font-bold mb-2">{location.name}</h2>
        {location.imageUrl && (
          <img src={location.imageUrl} alt={location.name} className="w-full h-64 object-cover mb-4 rounded" />
        )}
        <p className="mb-4">{location.description || 'No description provided.'}</p>

        {/* Small embedded map for the single location (optional) */}
        <div className="h-64">
