                  &center=${location.lat},${location.lng}&zoom=14`}
          />
        </div>
      </section>

      {/* Right column – list of all locations */}
      <aside className="p-4 border rounded bg-gray-50">
        <h3 className="text-xl font-semibold mb-3">All Locations</h3>
        <ul className="space-y-2">
