import sys

def solve() -> None:
    data = list(map(int, sys.stdin.read().strip().split()))
    if not data:
        return
    idx = 0
    results = []
    while idx < len(data):
        if idx + 1 >= len(data):
            break
        n, target = data[idx], data[idx + 1]
        idx += 2
        if idx + n > len(data):
            break
        coins = data[idx:idx + n]
        idx += n

        dp = [0] * (target + 1)
        dp[0] = 1
        for c in coins:
            if c > target:
                continue
            for amt in range(c, target + 1):
                dp[amt] += dp[amt - c]
        results.append(str(dp[target]))
    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()

