## 6️⃣ `src/routes/userRoutes.js` – All the endpoints

```js
// src/routes/userRoutes.js
import express from 'express';
import bcrypt from 'bcryptjs';          // or import bcrypt from 'bcrypt';
import { User } from '../models/User.js';
import { Role } from '../models/Role.js';

const router = express.Router();

/* --------------------------------------------------------------
   Helper: hash a plain password
   -------------------------------------------------------------- */
const hashPassword = async (plain) => {
  const saltRounds = Number(process.env.BCRYPT_SALT_ROUNDS) || 10;
  const salt = await bcrypt.genSalt(saltRounds);
  return bcrypt.hash(plain, salt);
};

/* --------------------------------------------------------------
   CREATE a new user
   -------------------------------------------------------------- */
router.post('/', async (req, res) => {
  try {
    const { name, password, roleId, location, tags } = req.body;

    // 1️⃣ Check if the user already exists (findOne)
    const existing = await User.findOne({ name }).exec();
    if (existing) {
      return res.status(409).json({ error: 'User already exists' });
    }

    // 2️⃣ Hash the password
    const hashed = await hashPassword(password);

    // 3️⃣ Build the document
    const user = new User({
      name,
      password: hashed,
      role: roleId,               // optional reference
      location,
      tags,
    });

    // 4️⃣ Save to DB (save)
    await user.save();

    // 5️⃣ Return the created user (lean + select to hide password)
    const created = await User.findById(user._id)
      .select('-password')
      .lean()
      .exec();

    res.status(201).json(created);
  } catch (err) {
    console.error('Create user error:', err);
    res.status(500).json({ error: 'Server error' });
  }
});

/* --------------------------------------------------------------
   READ – Get all users (demonstrates many query helpers)
   -------------------------------------------------------------- */
router.get('/', async (req, res) => {
  try {
    const {
      sort = 'name',
      limit = 20,
      skip = 0,
      fields,          // e.g. "name,createdAt"
      name,            // simple filter example
      role,            // filter by role id
      tag,             // filter by tags (array)
      regex,           // e.g. "?regex=adm"
    } = req.query;

    // Base query
    let query = User.find();

    // ---- Filtering -------------------------------------------------
    if (name) query = query.where('name').equals(name);
    if (role) query = query.where('role').equals(role);
    if (tag) query = query.where('tags').in([tag]); // $in
    if (regex) query = query.where('name').regex(new RegExp(regex, 'i')); // $regex

    // ---- Projection ------------------------------------------------
    if (fields) query = query.select(fields.split(',').join(' '));
    else query = query.select('-password'); // hide password by default

    // ---- Populate --------------------------------------------------
    query = query.populate('role', 'title'); // populate role.title only

    // ---- Sorting, pagination ----------------------------------------
    query = query.sort(sort).skip(Number(skip)).limit(Number(limit));

    // ---- Lean & exec ------------------------------------------------
    const users = await query.lean().exec();

    // ---- Count total documents (ignoring pagination) ---------------
    const total = await User.countDocuments(query.getFilter());

    res.json({ total, count: users.length, users });
  } catch (err) {
    console.error('Get users error:', err);
    res.status(500).json({ error: 'Server error' });
  }
});

/* --------------------------------------------------------------
   READ – Get a single user by ID (populate, lean, select)
   -------------------------------------------------------------- */
router.get('/:id', async (req, res) => {
  try {
    const user = await User.findById(req.params.id)
      .populate('role', 'title')
      .select('-password')
      .lean()
      .exec();

    if (!user) return res.status(404).json({ error: 'User not found' });

    res.json(user);
  } catch (err) {
    console.error('Get user by id error:', err);
    res.status(500).json({ error: 'Server error' });
  }
});

/* --------------------------------------------------------------
   UPDATE – Full replace (PUT) – uses findOneAndUpdate
   -------------------------------------------------------------- */
router.put('/:id', async (req, res) => {
  try {
    const { name, password, roleId, location, tags } = req.body;

    // Build the update object
    const update = { name, role: roleId, location, tags };

    // If password is supplied, hash it first
    if (password) update.password = await hashPassword(password);

    // findOneAndUpdate returns the *old* doc by default → set {new:true}
    const updated = await User.findOneAndUpdate(
      { _id: req.params.id },
      { $set: update },
      { new: true, runValidators: true }
    )
      .select('-password')
      .lean()
      .exec();

    if (!updated) return res.status(404).json({ error: 'User not found' });

    res.json(updated);
  } catch (err) {
    console.error('Update user error:', err);
    res.status(500).json({ error: 'Server error' });
  }
});

/* --------------------------------------------------------------
   PATCH – Partial update (demonstrates $set, $inc, $push, etc.)
   -------------------------------------------------------------- */
router.patch('/:id', async (req, res) => {
  try {
    const update = { ...req.body };

    // Example: if password is present, hash it
    if (update.password) {
      update.password = await hashPassword(update.password);
    }

    // Example: push a new tag (if tags is an array)
    if (update.addTag) {
      update.$push = { tags: update.addTag };
      delete update.addTag;
    }

    const patched = await User.findByIdAndUpdate(
      req.params.id,
      update,
      { new: true, runValidators: true }
    )
      .select('-password')
      .lean()
      .exec();

    if (!patched) return res.status(404).json({ error: 'User not found' });

    res.json(patched);
  } catch (err) {
    console.error('Patch user error:', err);
    res.status(500).json({ error: 'Server error' });
  }
});

/* --------------------------------------------------------------
   DELETE – Remove a user (findOneAndDelete)
   -------------------------------------------------------------- */
router.delete('/:id', async (req, res) => {
  try {
    const removed = await User.findOneAndDelete({ _id: req.params.id }).exec();

    if (!removed) return res.status(404).json({ error: 'User not found' });

    res.json({ message: 'User deleted', id: removed._id });
  } catch (err) {
    console.error('Delete user error:', err);
    res.status(500).json({ error: 'Server error' });
  }
});

/* --------------------------------------------------------------
   AGGREGATE – Example: count users per role
   -------------------------------------------------------------- */
router.get('/stats/role-count', async (req, res) => {
  try {
    const pipeline = [
      {
        $lookup: {
          from: 'roles',
          localField: 'role',
          foreignField: '_id',
          as: 'roleInfo',
        },
      },
      { $unwind: '$roleInfo' },
      {
        $group: {
          _id: '$roleInfo.title',
          users: { $sum: 1 },
        },
      },
      { $project: { role: '$_id', users: 1, _id: 0 } },
    ];

    const result = await User.aggregate(pipeline).exec();

    res.json(result);
  } catch (err) {
    console.error('Aggregate error:', err);
    res.status(500).json({ error: 'Server error' });
  }
});

/* --------------------------------------------------------------
   DISTINCT – Get all distinct tag values used by users
   -------------------------------------------------------------- */
router.get('/stats/distinct-tags', async (req, res) => {
  try {
    const tags = await User.distinct('tags').exec(); // distinct
    res.json({ tags });
  } catch (err) {
    console.error('Distinct tags error:', err);
    res.status(500).json({ error: 'Server error' });
  }
});

/* --------------------------------------------------------------
   ADVANCED SEARCH – Demonstrates $or, $and, $nor, $not, $exists,
   $type, $size, $elemMatch, $all, $slice, $mod, $in, $nin,
   $text, $geoNear, $near, $within, $intersects, etc.
   -------------------------------------------------------------- */
router.get('/search', async (req, res) => {
  try {
    const {
      q,                     // free‑text search (uses $text)
      minCreated, maxCreated,
      roleIds,               // comma‑separated list → $in
      excludeRoles,          // comma‑separated list → $nin
      lng, lat, radius,      // geo‑near query (in meters)
      modField, modDivisor, modRemainder, // $mod example
    } = req.query;

    let query = User.find();

    // ----- $text search -------------------------------------------------
    if (q) query = query.where({ $text: { $search: q } });

    // ----- Range query (createdAt) ------------------------------------
    if (minCreated) query = query.where('createdAt').gte(new Date(minCreated));
    if (maxCreated) query = query.where('createdAt').lte(new Date(maxCreated));

    // ----- $in / $nin ---------------------------------------------------
    if (roleIds) query = query.where('role').in(roleIds.split(','));
    if (excludeRoles) query = query.where('role').nin(excludeRoles.split(','));

    // ----- $mod ---------------------------------------------------------
    if (modField && modDivisor && modRemainder) {
      query = query.where(modField).mod(Number(modDivisor), Number(modRemainder));
    }

    // ----- Geo queries --------------------------------------------------
    if (lng && lat && radius) {
      // $nearSphere (or $geoNear via aggregation)
      query = query.where('location').near({
        center: {
          type: 'Point',
          coordinates: [Number(lng), Number(lat)],
        },
        maxDistance: Number(radius), // meters
        spherical: true,
      });
    }

    // ----- $or, $and, $nor, $not examples -------------------------------
    // Example: find users whose name starts with "admin" OR have tag "vip"
    query = query.or([
      { name: { $regex: '^admin', $options: 'i' } },
      { tags: 'vip' },
    ]);

    // Example: $and (implicit when you chain .where/.equals)
    // Example: $nor – exclude users that are admins OR have the tag "banned"
    query = query.nor([
      { name: { $regex: '^admin', $options: 'i' } },
      { tags: 'banned' },
    ]);

    // Example: $not – find users whose name does NOT contain "test"
    query = query.where('name').not({ $regex: 'test', $options: 'i' });

    // Example: $exists – only return users that have a role assigned
    query = query.where('role').exists(true);

    // Example: $type – ensure the "tags" field is an array
    query = query.where('tags').type('array');

    // Example: $size – users that have exactly 3 tags
    query = query.where('tags').size(3);

    // Example: $elemMatch – users that have a tag that matches a pattern
    query = query.where('tags').elemMatch({ $regex: '^dev', $options: 'i' });

    // Example: $all – users that contain both "node" and "mongo" tags
    query = query.where('tags').all(['node', 'mongo']);

    // Example: $slice – return only the first two tags (projection)
    query = query.select({ tags: { $slice: 2 } });

    // ----- Projection (select) -----------------------------------------
    query = query.select('-password'); // hide password

    // ----- Exec & lean --------------------------------------------------
    const results = await query.lean().exec();

    res.json({ count: results.length, results });
  } catch (err) {
    console.error('Advanced search error:', err);
    res.status(500).json({ error: 'Server error' });
  }
});

export default router;
```

**What you see in the file above**

| Requirement | Where it appears |
|-------------|------------------|
| **Express router** | `router = express.Router()` |
| **body‑parser** (used in `app.js`) | – |
| **async/await** | All route handlers are `async` |
| **try / catch** | Every handler wraps the logic in `try { … } catch (err) { … }` |
| **bcrypt** | `hashPassword` helper (`bcrypt.genSalt` + `bcrypt.hash`) |
| **Mongoose connection** | `connectDB()` in `app.js` |
| **Mongoose schema / model** | `User` (and optional `Role`) |
| **save** | `await user.save()` in the POST route |
| **findOne** | `User.findOne({ name })` – duplicate‑check |
| **findOneAndUpdate** | `router.put('/:id')` uses `findOneAndUpdate` |
| **findOneAndDelete** | `router.delete('/:id')` uses `findOneAndDelete` |
| **find** | `router.get('/')` starts with `User.find()` |
| **findById** | `router.get('/:id')` |
| **findByIdAndUpdate** | `router.patch('/:id')` (or you could use `findByIdAndUpdate`) |
| **findByIdAndDelete** | Not used directly because `findOneAndDelete` does the same, but you can replace it with `User.findByIdAndDelete(req.params.id)` – the code works either way |
| **populate** | `.populate('role', 'title')` |
| **lean** | `.lean()` on every read query |
| **exec** | `.exec()` after every query (or after `countDocuments`) |
| **select** | `.select('-password')` or custom fields via query param |
