  -H "Content-Type: application/json" \
  -d '{"name":"alice","password":"secret123","roleId":"<role‑id>","location":{"coordinates":[-73.9857,40.7484]},"tags":["node","mongo"]}'

# 3️⃣ List users (pagination, sorting, projection)
