  -H "Content-Type: application/json" \
  -d '{"name":"alice‑updated","password":"newPass"}'

# 6️⃣ Patch (PATCH) – add a tag
curl -X PATCH http://localhost:4000/api/users/<user‑id> \
  -H "Content-Type: application/json" \
  -d '{"addTag":"backend"}'

# 7️⃣ Delete
