### 2.2 Database Schema & Init Script

Create `db.js` – a tiny wrapper that creates the table on first run and exposes helper functions.

```js
// db.js
const sqlite = require('sqlite3').verbose();
const path   = require('path');

const DB_PATH = path.join(__dirname, 'highscore.db');
const db = new sqlite.Database(DB_PATH, err => {
  if (err) throw err;
  console.log('🗄️  Connected to SQLite DB');
});

/* -------------------------------------------------------------
   Initialise the table (run once). If the row already exists we
   leave it untouched – the high‑score survives restarts.
   ------------------------------------------------------------- */
db.serialize(() => {
  db.run(`
    CREATE TABLE IF NOT EXISTS highscore (
      id INTEGER PRIMARY KEY CHECK (id = 1),   -- always a single row
      value INTEGER NOT NULL
    )
  `);

  // Insert a default row (value = 0) if the table is empty
  db.get(`SELECT COUNT(*) AS cnt FROM highscore`, (err, row) => {
    if (err) throw err;
    if (row.cnt === 0) {
      db.run(`INSERT INTO highscore (id, value) VALUES (1, 0)`);
      console.log('🔧 Inserted initial highscore = 0');
    }
  });
});

/* -------------------------------------------------------------
   Helper: read the current high‑score
   ------------------------------------------------------------- */
function getHighScore() {
  return new Promise((resolve, reject) => {
    db.get(`SELECT value FROM highscore WHERE id = 1`, (err, row) => {
      if (err) return reject(err);
      resolve(row?.value ?? 0);
    });
  });
}

/* -------------------------------------------------------------
   Helper: try to set a new high‑score.
   The whole operation runs inside a transaction so that
   concurrent requests cannot corrupt the value.
   ------------------------------------------------------------- */
function tryUpdateHighScore(candidate) {
  return new Promise((resolve, reject) => {
    db.serialize(() => {
      db.run('BEGIN IMMEDIATE TRANSACTION'); // lock the row

      db.get(`SELECT value FROM highscore WHERE id = 1`, (err, row) => {
        if (err) {
          db.run('ROLLBACK');
          return reject(err);
        }

        const current = row?.value ?? 0;
        if (candidate > current) {
          db.run(`UPDATE highscore SET value = ? WHERE id = 1`, candidate, err2 => {
            if (err2) {
              db.run('ROLLBACK');
              return reject(err2);
            }
            db.run('COMMIT');
            resolve(candidate); // new high‑score
          });
        } else {
          db.run('COMMIT');
          resolve(current); // unchanged
        }
      });
    });
  });
}

/* -------------------------------------------------------------
   Export the helpers
   ------------------------------------------------------------- */
module.exports = {
  getHighScore,
  tryUpdateHighScore,
};
```

### 2.3 Express Server (`server.js`)

```js
