  // 1️⃣ Generate a random integer 1‑100 (inclusive)
  const value = Math.floor(Math.random() * 100) + 1;

  try {
    // 2️⃣ Try to store it as the new high‑score (if it beats the old one)
    const high = await tryUpdateHighScore(value);

    // 3️⃣ Respond with both numbers
